(397,	'IFRA_STD_105',	NULL,	'40',	'1975\n2002',	'2006',	'Not applicable.',	'Not applicable.',	'Alantroot oil',	'84012-20-4',	'The scope of this Standard includes, but is not limited to the CAS number(s) indicated above; any other CAS number(s) used to identify this fragrance ingredient should be considered in scope as well.',	'Alantroot oil (Inula helenium)\nElecampane oil\nInula helenium oil',	NULL,	'',	'This material should not be used as a fragrance ingredient. ',	'',	'',	'',	'PROHIBITION',	'DERMAL SENSITIZATION',	'None to consider',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	'',	''),
